def solve(grid):
    n_rows = len(grid)
    n_cols = len(grid[0]) if n_rows else 0

    # locate the unique non‑zero cell
    v = None
    orig_r = orig_c = None
    for i in range(n_rows):
        for j in range(n_cols):
            if grid[i][j] != 0:
                v = grid[i][j]
                orig_r, orig_c = i, j
                break
        if v is not None:
            break

    if v is None:            # no non‑zero value – nothing to transform
        return grid

    # prepare output grid filled with zeros
    out = [[0] * n_cols for _ in range(n_rows)]

    # vertical stripe: same parity as original column, to the right
    for col in range(orig_c, n_cols):
        if (col - orig_c) % 2 == 0:
            for row in range(n_rows):
                out[row][col] = v

    # place the value 5 at the top or bottom row for odd offsets
    d = 1
    while orig_c + d < n_cols:
        col = orig_c + d
        if d % 4 == 1:
            out[0][col] = 5
        elif d % 4 == 3:
            out[n_rows - 1][col] = 5
        d += 2

    return out

